ana_liste = {
    "KYS-PR-003": ("C", "onayli"),
    "KYS-PR-007": ("B", "onayli"),
    "KYS-TL-012": ("D", "taslak"),
    "KYS-FR-031": ("A", "onayli"),
}
kullanim = [
    ("yayin-wiki", "KYS-PR-003", "C"),
    ("test-lab", "KYS-PR-007", "A"),
    ("destek", "KYS-TL-012", "D"),
    ("yayin-wiki", "KYS-FR-031", "A"),
    ("paylasim", "KYS-PR-009", "B"),
]
bulgu = 0
for yer, kod, rev in kullanim:
    if kod not in ana_liste:
        durum = "LISTEDE YOK"
    else:
        gecerli, onay = ana_liste[kod]
        if onay != "onayli":
            durum = "ONAYSIZ"
        elif rev < gecerli:
            durum = "ESKI REV " + rev + "<" + gecerli
        else:
            durum = "tamam"
    if durum != "tamam":
        bulgu += 1
    print(yer, kod, durum)
print("bulgu", bulgu, "/", len(kullanim))
print("oran", round(100 * bulgu / len(kullanim), 1))
